pat='I _ _ I _ I _ _ I _ J _'.split()
opts={'A':'J I J I J I I','B':'J I I I J J I','C':'I J I I J J I','D':'I I J J J I J'}
def fill(o):
    it=iter(o.split()); return ''.join(next(it) if c=='_' else c for c in pat)
def periodic(s):
    return any(all(s[i]==s[i%p] for i in range(len(s))) for p in range(2,5))
fits=[k for k,v in opts.items() if periodic(fill(v))]
assert fits==['A']
